package textutil

import (
	"regexp"
	"strings"
)

// ideContextTagRegex matches IDE-injected context tags like <ide_opened_file>...</ide_opened_file>
// and <ide_selection>...</ide_selection>. These are injected by the VSCode extension.
var ideContextTagRegex = regexp.MustCompile(`(?s)<ide_[^>]*>.*?</ide_[^>]*>`)

// systemTagRegexes matches system-injected context tags that shouldn't appear in user-facing text.
// Each tag type needs its own regex since Go's regexp doesn't support backreferences.
var systemTagRegexes = []*regexp.Regexp{
	regexp.MustCompile(`(?s)<local-command-caveat[^>]*>.*?</local-command-caveat>`),
	regexp.MustCompile(`(?s)<system-reminder[^>]*>.*?</system-reminder>`),
	regexp.MustCompile(`(?s)<command-name[^>]*>.*?</command-name>`),
	regexp.MustCompile(`(?s)<command-message[^>]*>.*?</command-message>`),
	regexp.MustCompile(`(?s)<command-args[^>]*>.*?</command-args>`),
	regexp.MustCompile(`(?s)<local-command-stdout[^>]*>.*?</local-command-stdout>`),
	regexp.MustCompile(`</?user_query>`),                              // Cursor wraps user text in <user_query> tags; strip tags but keep content
	regexp.MustCompile(`<timestamp(\s[^>]*)?>[^<\n]*</timestamp\s*>`), // Cursor-injected send-time date; single-line body only
}

// StripIDEContextTags removes IDE-injected context tags from prompt text.
// The VSCode extension injects tags like:
//   - <ide_opened_file>...</ide_opened_file> - currently open file
//   - <ide_selection>...</ide_selection> - selected code in editor
//
// Also removes system-injected tags like:
//   - <local-command-caveat>...</local-command-caveat>
//   - <system-reminder>...</system-reminder>
//   - <command-name>...</command-name>
//
// These shouldn't appear in commit messages or session descriptions.
func StripIDEContextTags(text string) string {
	result := ideContextTagRegex.ReplaceAllString(text, "")
	for _, re := range systemTagRegexes {
		result = re.ReplaceAllString(result, "")
	}
	return strings.TrimSpace(result)
}

package textutil

import "testing"

func TestStripIDEContextTags(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "no IDE tags",
			input:    "make the returned number red",
			expected: "make the returned number red",
		},
		{
			name:     "ide_opened_file tag only",
			input:    "<ide_opened_file>The user opened the file /path/to/file.md in the IDE. This may or may not be related to the current task.</ide_opened_file>",
			expected: "",
		},
		{
			name:     "ide_opened_file with real prompt",
			input:    "<ide_opened_file>The user opened the file /path/to/file.md in the IDE.</ide_opened_file>\n\nmake the returned number red",
			expected: "make the returned number red",
		},
		{
			name:     "ide_selection tag",
			input:    "<ide_selection file=\"/path/file.go\" lines=\"10-20\">selected code here</ide_selection>\n\nrefactor this function",
			expected: "refactor this function",
		},
		{
			name:     "multiline ide_selection",
			input:    "<ide_selection>func main() {\n    fmt.Println(\"hello\")\n}</ide_selection>\n\noptimize this",
			expected: "optimize this",
		},
		{
			name:     "multiple IDE tags",
			input:    "<ide_opened_file>file.go</ide_opened_file>\n\n<ide_selection>some code</ide_selection>\n\nplease fix the bug",
			expected: "please fix the bug",
		},
		{
			name:     "unknown future ide tag",
			input:    "<ide_cursor_position line=\"42\" col=\"10\">cursor info</ide_cursor_position>\n\nhelp me here",
			expected: "help me here",
		},
		{
			name:     "preserves other XML-like content",
			input:    "<user_note>important</user_note> and <system>info</system>",
			expected: "<user_note>important</user_note> and <system>info</system>",
		},
		{
			name:     "empty string",
			input:    "",
			expected: "",
		},
		{
			name:     "whitespace only after stripping",
			input:    "<ide_opened_file>file.md</ide_opened_file>   \n\n   ",
			expected: "",
		},
		{
			name:     "local-command-caveat tag",
			input:    "<local-command-caveat>Caveat: The messages below were generated by the user while running local commands.</local-command-caveat>my actual prompt",
			expected: "my actual prompt",
		},
		{
			name:     "system-reminder tag",
			input:    "<system-reminder>This is a system reminder.</system-reminder>\n\nactual user text",
			expected: "actual user text",
		},
		{
			name:     "command-name tag",
			input:    "<command-name>/release-notes</command-name>",
			expected: "",
		},
		{
			name:     "multiple system tags",
			input:    "<local-command-caveat>caveat text</local-command-caveat><command-name>/test</command-name><command-message>msg</command-message><command-args>args</command-args>real prompt here",
			expected: "real prompt here",
		},
		{
			name:     "local-command-stdout tag",
			input:    "<local-command-stdout>output from command</local-command-stdout>\n\nuser prompt",
			expected: "user prompt",
		},
		{
			name:     "mixed IDE and system tags",
			input:    "<ide_opened_file>file.go</ide_opened_file><system-reminder>reminder</system-reminder>\n\nactual prompt",
			expected: "actual prompt",
		},
		{
			name:     "cursor user_query tags stripped keeping content",
			input:    "<user_query>\ncreate a file with contents 'a'\n</user_query>",
			expected: "create a file with contents 'a'",
		},
		{
			name:     "cursor user_query with surrounding text",
			input:    "<user_query>\nhello world\n</user_query>",
			expected: "hello world",
		},
		{
			name:     "cursor timestamp block removed, user_query unwrapped",
			input:    "<timestamp>Tuesday, Aug 18, 2026, 2:37 PM GMT+2</timestamp>\n<user_query>\nfix the login bug\n</user_query>",
			expected: "fix the login bug",
		},
		{
			name:     "timestamp with attributes stripped",
			input:    "<timestamp tz=\"GMT+2\">Tuesday, Aug 18, 2026, 2:37 PM</timestamp>\nfix it",
			expected: "fix it",
		},
		{
			name:     "multi-line timestamp span preserved",
			input:    "rename the <timestamp> element\nand update </timestamp> closers too",
			expected: "rename the <timestamp> element\nand update </timestamp> closers too",
		},
		{
			name:     "timestamps wrapper tag not mangled",
			input:    "see <timestamps><timestamp>a</timestamp></timestamps> nested",
			expected: "see <timestamps></timestamps> nested",
		},
		{
			name:     "single-line timestamp inside pasted xml still stripped",
			input:    "```xml\n<event>\n  <timestamp>2026-01-01</timestamp>\n  <level>ERROR</level>\n</event>\n```",
			expected: "```xml\n<event>\n  \n  <level>ERROR</level>\n</event>\n```",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			result := StripIDEContextTags(tt.input)
			if result != tt.expected {
				t.Errorf("StripIDEContextTags() = %q, want %q", result, tt.expected)
			}
		})
	}
}

